INSERT INTO temp_import_pages VALUES ('{"pageId": "e0800000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 80, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "80", "printedPageNumber": 80, "pdfPageNumber": 463, "sequenceIndex": 70, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0800100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Story—XII", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0800200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Story—XIII", "sourceIdentifier": null, "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0800000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}, {"id": "f0800100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "promise of liberty,\" Umar bin Abdul Aziz (Rahmatullah alaih) took those dinaars from the slave and deposited them in the Baitul Maal, and advised him to run away to some distant place where he could not be seized.\n\nJust before his death, Muslimah (Rahmatullah alaih) came to him and said, \"Nobody has ever treated his children as you are doing. None of your thirteen sons has anything to live on.\" He sat up in his bed and said, \"I have not held back from my sons what they were entitled to. I have, of course, refused them what was actually due to others. If my sons are righteous, then Allah will surely be their guardian as He has said in His Book: He is the guardian of the righteous (VII: 196)'', but if they are wrong-doers, then why should I care for them?\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}, {"id": "f0800200-0000-4000-8000-000000000001", "structuralNodeId": "b0800100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Story—XII", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}, {"id": "f0800300-0000-4000-8000-000000000001", "structuralNodeId": "b0800100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Muhammad bin Munkadir (Rahmatullah alaih) was a Hafiz of Hadith. One night, he wept excessively in his Tahajjud. When someone inquired about it, he said, \"During Qiraat, I came across the following words of the Qur''an:", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}, {"id": "f0800400-0000-4000-8000-000000000001", "structuralNodeId": "b0800100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "وَبَدَا لَهُمْ سَيِّئَاتُ مَا كَسَبُوا وَحَاقَ بِهِمْ مَا كَانُوا بِهِ يَسْتَهْزِئُونَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}, {"id": "f0800500-0000-4000-8000-000000000001", "structuralNodeId": "b0800100-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"And the evils that they earned will confront them; and they will be surrounded by what they used to scoff at.\" (XXXIX: 48)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}, {"id": "f0800600-0000-4000-8000-000000000001", "structuralNodeId": "b0800100-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "He was very anxious and worried at the time of his death, and said that these same words of the Qur''an were looming before him.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}, {"id": "f0800700-0000-4000-8000-000000000001", "structuralNodeId": "b0800200-0000-4000-8000-000000000001", "sequenceIndex": 7, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Story—XIII", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}, {"id": "f0800800-0000-4000-8000-000000000001", "structuralNodeId": "b0800200-0000-4000-8000-000000000001", "sequenceIndex": 8, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Thaabit Banaani (Rahmatullah alaih) is another Hafiz of Hadith. He used to cry a great deal while supplicating before Allah. Someone warned him that he would lose his eyesight if he did not stop weeping like that. He replied to him, \"What use are these eyes if these do not weep before Allah.\"\n\nHe used to ask in his prayer, \"O, Allah! Permit me to offer my salaat in my grave, if ever you grant this privilege to any of Thy slaves!\" Abu Sanaan (Rahmatullah alaih) narrates, \"By Allah! I was among those present at the burial of Thaabit Banaani. Just after he had been placed in his grave, one of the bricks from the side fell off. I peeped into the pit to find to my great amazement, that Thaabit was offering", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 80"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0810000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 81, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "81", "printedPageNumber": 81, "pdfPageNumber": 464, "sequenceIndex": 71, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0810000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (b)—Stories of the Pious", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 81"}, {"id": "f0810100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "his salaat. I said to a person standing by my side; ''Look what is that.'' He advised me to keep quiet. After the burial, we went to his daughter and inquired from her, ''What was the special practice of your father?'' She wanted to know what made us put that question. We related to her the incident at the grave. She said, ''He has been constant in Tahajjud for fifty years and prayed every morning before Allah to allow him to offer salaat in the grave if that privilege could be granted to anybody.''\n\nBefore finishing this chapter, I give below the pursuits (as regards salaat) of some of our eminent Muslim ancestors:\n\n1. Imaam Ahmad bin Hambal (Rahmatullah alaih) is the famous Imaam of one of the four schools of Muslim jurisprudence. Besides being engaged in his usual work, he used to offer daily three hundred rakaats of nafl salaat. After he was lashed by the king for refusal to submit to the royal edict, he became very weak and reduced his routine nafl salaat to one hundred and fifty rakaats. We should not forget that he was eighty at that time.\n\n2. Imaam Shaafi''ee (Rahmatullah alaih) another eminent Imaam of Muslim jurisprudence, used to finish reciting the Qur''an sixty times in his salaat during Ramadhaan. A person narrates, \"I remained with Imaam Shaafi''ee for several days and found him sleeping only for a while at night.\"\n\n3. Imaam Abu Haneefa (Rahmatullah alaih) is famous for his vigil. It is said that for thirty, forty or fifty years (according to the information of different narrators) he offered his Fajr prayer with the wudhu for Ishaa. He would go to sleep only for a few minutes in the afternoon saying, \"It is sunnat to sleep in the afternoon.\"\n\n4. It is said about Sa''eed bin Musayyab (Rahmatullah alaih) that for fifty years he offered his Fajr salaat with the wudhu performed at Ishaa. Imaam Ghazzali (Rahmatullah alaih) on the authority of Abu Taalib Makki reported the same practice by no less than forty Taabi''ees, some of whom had been doing it for forty years continuously.\n\n5. Muhammad bin Nasr (Rahmatullah alaih) is a famous Muhaddith. His devotion to salaat had no", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 81"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0820000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 82, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "82", "printedPageNumber": 82, "pdfPageNumber": 465, "sequenceIndex": 72, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0820000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 82"}, {"id": "f0820100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "parallel. Once while in salaat, he was stung on his forehead by a wasp and though blood came out, neither did he stir nor did he allow it to disturb his devotion in salaat. It is said that in salaat, he stood motionless like a stick planted in the ground.\n\n6. It is reported about Baqi bin Mukhallid (Rahmatullah alaih) that he used to recite the complete Qur''an every night in thirteen rakaats of Tahajjud and Witr.\n\n7. Hannaad (Rahmatullah alaih) is a Muhaddith. One of his pupils narrates, \"Hannaad used to weep very much. One day after he had finished our lesson in the morning, he continued to offer nafl salaat till midday. He went to his place for a short interval and then returned for his Zuhr. He again engaged himself in nafl salaat till Asr. Between Asr and Maghrib, he recited the Qur''an. I left him after Maghrib. I said to one of his neighbours, ''Our Shaikh prays so much. It is really wonderful.'' He said, ''He had been doing this for the last seventy years. You will wonder still more if you see his prayers during the night.''\"\n\n8. Masrooq (Rahmatullah alaih) is another Muhaddith. His wife narrates, \"He used to offer such long rakaats that his legs would get swollen and I sat behind weeping in pity for him.\"\n\n9. Abu Itaab Sulami (Rahmatullah alaih) is reported to have been fasting during the day and weeping during the night for full forty years.\n\n10. It is said about a Sayyid that continuously for twelve days he has been offering his salaat with the same wudhu. For fifteen years, his back had not touched the bed. He would also go without food for days together.\n\nBesides the above, there are numerous records of the pious pursuits of the heroes of Islamic History. It is difficult to cover all of them in this book. All that has been said here is sufficient to serve as examples. May Allah, through His Grace, grant me and the readers of this book the strength to follow in the footsteps of these blessed people! Aameen!", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 82"}]}'::jsonb);
FOR v_page IN SELECT page_data FROM temp_import_pages LOOP
  PERFORM import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, v_page);
END LOOP;
END;
